mapper.select:
select * from ( select rownum rn, TMP.* from ( select e.emp_no, e.emp_name, d.dept_name, p.position_name, e.emp_state, e.emp_level, e.emp_email, e.emp_contact, e.emp_birth, e.emp_post, e.emp_address1, e.emp_address2, ep.attach_no from emp E join dept D on E.emp_dept_no = D.dept_no join position P on E.emp_position_no = P.position_no LEFT JOIN emp_profile ep ON e.emp_no = ep.emp_no
D.dept_name LIKE '%' || #{keyword} || '%'
or P.position_name LIKE '%' || #{keyword} || '%'
or E.emp_state = #{keyword}
or e.emp_name LIKE '%' || #{keyword} || '%'
order by e.emp_no asc )TMP ) where rn between #{pageVO.beginRownum} and #{pageVO.endRownum}

